export function nowPanelBoardPartsFinished(input: { closed: string; count: number }): string {
  const closed = input.closed;
  const count = formatNumber(input.count);
  switch (currentLanguage()) {
    case "ar":
      switch (pluralCategory(input.count)) {
        case "zero":
          return `اكتمل ${closed} من ${count} جزء`;
        case "one":
          return `اكتمل ${closed} من ${count} جزء`;
        case "two":
          return `اكتمل ${closed} من ${count} جزأين`;
        case "few":
          return `اكتمل ${closed} من ${count} أجزاء`;
        case "many":
          return `اكتمل ${closed} من ${count} جزءًا`;
        default:
          return `اكتمل ${closed} من ${count} جزء`;
      }
    case "de":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${closed} von ${count} Teil fertig`;
        default:
          return `${closed} von ${count} Teilen fertig`;
      }
    case "es":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${closed} de ${count} partes terminadas`;
        case "many":
          return `${closed} de ${count} de partes terminadas`;
        default:
          return `${closed} de ${count} partes terminadas`;
      }
    case "fr":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${closed} partie sur ${count} terminée`;
        case "many":
          return `${closed} parties sur ${count} terminées`;
        default:
          return `${closed} parties sur ${count} terminées`;
      }
    case "ja":
      switch (pluralCategory(input.count)) {
        default:
          return `パート${count}件中${closed}件が完了`;
      }
    case "ko":
      switch (pluralCategory(input.count)) {
        default:
          return `부분 ${count}개 중 ${closed}개 완료`;
      }
    case "pt-BR":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${closed} de ${count} parte concluída`;
        case "many":
          return `${closed} de ${count} partes concluídas`;
        default:
          return `${closed} de ${count} partes concluídas`;
      }
    case "zh-Hans":
      switch (pluralCategory(input.count)) {
        default:
          return `${count} 个部分中已完成 ${closed} 个`;
      }
    case "zh-Hant":
      switch (pluralCategory(input.count)) {
        default:
          return `${count} 個部分中已完成 ${closed} 個`;
      }
    case "en-XA":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `[${closed} öƒ ${count} þáŕţš ƒîñîšĥéð ~~~~~~~]`;
        default:
          return `[${closed} öƒ ${count} þáŕţš ƒîñîšĥéð ~~~~~~~]`;
      }
    case "ar-XB":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `${closed}\u202e of \u202c${count}\u202e parts finished\u202c`;
        default:
          return `${closed}\u202e of \u202c${count}\u202e parts finished\u202c`;
      }
  }
  switch (pluralCategory(input.count)) {
    case "one":
      return `${closed} of ${count} parts finished`;
    default:
      return `${closed} of ${count} parts finished`;
  }
}

